// Shared inputs for the report-runtime suites (DEL-57, DEL-72, DEL-74): every example report
// that renders without a connector, plus one fixture with the chart forms the examples lack,
// generated by the release CLI and served from one loopback origin.
import { cpSync, mkdirSync, writeFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { dirname, join } from 'node:path';
import type { Page } from 'playwright';
import { cli, root, serveStatic, verificationShard } from './browser-harness.ts';
import type { ChartModel } from './report-model.ts';
import { reportCohort } from '../tools/rv-gate/lib/report-inputs.mts';

const fence = (value: object) => `\n\`\`\`chart\n${JSON.stringify(value)}\n\`\`\`\n`;
const months = ['2024-01', '2024-02', '2024-03', '2024-04', '2024-05', '2024-06'];
const regions = ['North', 'South', 'East'];
const rows = months.flatMap((month, m) => regions.map((region, r) => ({ month, region, sales: 40 + m * 7 + r * 11 - (m * r) % 5, share: (r + 1) / 6 })));

/** Area, stacked bars, facets, pie and heatmap in one report: the forms the examples lack. */
export const FORMS = '---\ntitle: Chart forms\nversion: "1"\n---\n\nEvery remaining form, each with a title.\n'
  + fence({ type: 'area', title: 'Stacked area', encoding: { x: 'month', y: 'sales', color: 'region' }, stack: true, data: { inline: rows } })
  + fence({ type: 'bar', title: 'Stacked bars', encoding: { x: 'month', y: 'sales', color: 'region' }, stack: true, data: { inline: rows } })
  + fence({ type: 'line', title: 'Faceted lines', encoding: { x: 'month', y: 'sales', facet: 'region' }, data: { inline: rows } })
  + fence({ type: 'pie', title: 'Shares', encoding: { x: 'region', y: 'share' }, data: { inline: rows.slice(0, 3) } })
  + fence({ type: 'heatmap', title: 'Sales by month and region', encoding: { x: 'month', y: 'region', color: 'sales' }, data: { inline: rows } });

type GenerateResult = { ok?: boolean; diagnostics?: { code: string; level: string; message: string; path?: string; details?: { chartId?: string } }[] };

interface ReportOptions {
  style?: string;
  only?: readonly string[];
  extra?: Record<string, string>;
  files?: Record<string, Record<string, string | Buffer>>;
  failing?: readonly string[];
  shard?: boolean;
}

/**
 * Generate every input under `dir` and serve them; returns the base URL, the names and `close`.
 * `only` limits the examples, `extra` adds fixtures by name instead of the chart forms, and
 * `files` writes data files beside a fixture, keyed by fixture name and relative path, and
 * `failing` names fixtures whose errors are expected. `generated` holds each CLI JSON result.
 */
export async function reports(dir: string, { style, only, extra = { forms: FORMS }, files = {}, failing = [], shard = false }: ReportOptions = {}) {
  const out = join(dir, 'reports');
  mkdirSync(out, { recursive: true });
  const examples = reportCohort(root, { only, extra: [] });
  // Only an explicitly sharded consumer reads the selector. Other suites retain every input.
  const selection = shard ? verificationShard([...examples, ...Object.keys(extra)], { key: name => name }) : undefined;
  const selected = selection && new Set(selection.cases);
  const names = [];
  for (const name of examples) {
    if (selected && !selected.has(name)) continue;
    const source = join(root, 'examples', name);
    cpSync(source, join(out, name), { recursive: true });
    names.push(name);
  }
  for (const [name, source] of Object.entries(extra)) {
    if (selected && !selected.has(name)) continue;
    mkdirSync(join(out, name));
    writeFileSync(join(out, name, 'report.rmd'), source);
    for (const [path, text] of Object.entries(files[name] ?? {})) {
      mkdirSync(dirname(join(out, name, path)), { recursive: true });
      writeFileSync(join(out, name, path), text);
    }
    names.push(name);
  }
  const generated: Record<string, GenerateResult> = {};
  for (const name of names) {
    const args = ['generate', join(out, name, 'report.rmd'), '--format', 'json'];
    if (style) args.push('--style', style);
    let stdout;
    try {
      stdout = execFileSync(cli, args, { cwd: root, stdio: 'pipe', encoding: 'utf8' });
    } catch (error) {
      // A fixture listed in `failing` reports errors on purpose: the CLI still writes the report.
      if (!failing.includes(name) || !(error instanceof Error) || !('status' in error && error.status === 1) || !('stdout' in error && typeof error.stdout === 'string')) throw error;
      stdout = error.stdout;
    }
    generated[name] = JSON.parse(stdout);
  }
  const server = await serveStatic(Object.fromEntries(names.map(name => [`/${name}/`, join(out, name, 'Rendered')])));
  return { base: server.base, names, generated, close: server.close, ...(selection && { shard: selection.shard }) };
}

/** Wait for the runtime and settled charts, returning every model by default. */
export function settle(page: Page, timeout?: number, options?: { models?: true }): Promise<ChartModel[]>;
export function settle(page: Page, timeout: number | undefined, options: { models: false }): Promise<undefined>;
export async function settle(page: Page, timeout = 45_000, { models = true }: { models?: boolean } = {}) {
  await page.waitForFunction(() => window.__richview, null, { timeout });
  return page.evaluate(async (models) => {
    await window.__richview!.settled();
    return models ? window.__richview!.charts() : undefined;
  }, models);
}

/** Each figure's boxes and visible state, read from the DOM. */
export function figures(page: Page) {
  return page.evaluate(() => [...document.querySelectorAll('figure[data-rv-chart]')].map(figure => {
    const box = (node: Element | null) => {
      if (!node) return null;
      const r = node.getBoundingClientRect();
      return { x: r.x, y: r.y, width: r.width, height: r.height };
    };
    const notice = figure.querySelector<HTMLElement>('.rv-chart__notice');
    return {
      id: figure.id,
      figure: box(figure),
      frame: box(figure.querySelector('.rv-chart__frame')),
      title: figure.querySelector('.rv-chart__title')?.textContent ?? null,
      label: figure.querySelector('.rv-chart__frame')?.getAttribute('aria-label') ?? null,
      notice: notice && !notice.hidden && getComputedStyle(notice).display !== 'none' ? notice.textContent : null,
      canvas: figure.querySelectorAll('canvas').length,
      svg: figure.querySelectorAll('svg:not(.rv-chart__action svg, .rv-chart__controls svg, .rv-chart__overview svg, .rv-chart__legend svg)').length,
      img: figure.querySelectorAll('img').length,
    };
  }));
}
